    <script>
      (function() {
        const urlParams = new URLSearchParams(window.location.search);
        const urlTheme = urlParams.get('theme') || (urlParams.has('dark') ? 'dark' : (urlParams.has('light') ? 'light' : null));
        const theme = urlTheme || localStorage.getItem('color-theme');
        if (theme === 'dark' || (!theme && document.documentElement.classList.contains('dark'))) {
          document.documentElement.classList.add('dark');
        } else {
          document.documentElement.classList.remove('dark');
        }
        window.tailwind = {
          config: {
            darkMode: 'class'
          }
        };
      })();
