<style>
  :root {
    --forest-primary: #2E6F40;
    --forest-dark: #1E4C2B;
    --forest-hover: #245833;
    --forest-mint: #EAF7EE;
    --forest-accent: #68BA7F;
    --whatsapp-color: #25D366;
  }

  /* ── HERO BANNER LIGHT & DARK ── */
  .contact-hero {
    background: linear-gradient(135deg, #f0fdf9 0%, #ffffff 50%, #f6f9f8 100%);
    padding: 60px 24px 44px;
    text-align: center;
    position: relative;
    overflow: hidden;
    border-bottom: 1px solid #e5e7eb;
    transition: background 0.3s ease, border-color 0.3s ease;
  }
  .contact-hero::before {
    content: '';
    position: absolute;
    inset: 0;
    background:
      radial-gradient(ellipse at 25% 60%, rgba(46, 111, 64, 0.08) 0%, transparent 55%),
      radial-gradient(ellipse at 75% 30%, rgba(37, 211, 102, 0.06) 0%, transparent 55%);
    pointer-events: none;
  }
  html.dark .contact-hero {
    background: linear-gradient(135deg, #0f172a 0%, #0d2b22 50%, #0f1f2e 100%);
    border-bottom-color: rgba(255, 255, 255, 0.06);
  }
  html.dark .contact-hero::before {
    background:
      radial-gradient(ellipse at 25% 60%, rgba(46, 111, 64, 0.15) 0%, transparent 55%),
      radial-gradient(ellipse at 75% 30%, rgba(37, 211, 102, 0.08) 0%, transparent 55%);
  }

  .contact-hero-tag {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(46, 111, 64, 0.08);
    border: 1px solid rgba(46, 111, 64, 0.25);
    color: #2E6F40;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    padding: 6px 16px;
    border-radius: 9999px;
    margin-bottom: 16px;
    transition: all 0.3s ease;
  }
  html.dark .contact-hero-tag {
    background: rgba(46, 111, 64, 0.18);
    border-color: rgba(46, 111, 64, 0.4);
    color: #34d399;
  }

  .contact-hero h1 {
    font-size: clamp(28px, 4.5vw, 48px);
    font-weight: 900;
    color: #111827;
    line-height: 1.15;
    margin: 0 0 14px;
    letter-spacing: -0.5px;
    transition: color 0.3s ease;
  }
  html.dark .contact-hero h1 {
    color: #ffffff;
  }
  .contact-hero h1 span {
    color: #2E6F40 !important;
  }
  html.dark .contact-hero h1 span {
    color: #34d399 !important;
  }

  .contact-hero p {
    font-size: clamp(15px, 2vw, 17px);
    color: #4b5563;
    max-width: 680px;
    margin: 0 auto;
    line-height: 1.7;
    transition: color 0.3s ease;
  }
  html.dark .contact-hero p {
    color: rgba(255, 255, 255, 0.75);
  }

  /* ── MAIN CONTENT CONTAINER LIGHT & DARK ── */
  .contact-body-wrapper {
    background: #ffffff;
    color: #111827;
    padding: 44px 20px 60px;
    transition: background-color 0.3s ease, color 0.3s ease;
  }
  html.dark .contact-body-wrapper {
    background: #0b0f19;
    color: #f9fafb;
  }

  .contact-content-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 32px;
    max-width: 1240px;
    margin: 0 auto;
  }
  @media (min-width: 1024px) {
    .contact-content-grid {
      grid-template-columns: 420px 1fr;
      gap: 36px;
