<script>
(function() {
    // Dynamic API Base URL
    function getApiBaseUrl() {
        if (window.CHOWCHAK_CONFIG && window.CHOWCHAK_CONFIG.apiHost) {
            return window.CHOWCHAK_CONFIG.apiHost.replace(/\/$/, '');
        }
        if (window.TABLETRACK_CONFIG && window.TABLETRACK_CONFIG.apiHost) {
            return window.TABLETRACK_CONFIG.apiHost.replace(/\/$/, '');
        }
        const isLocal = (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');
        return isLocal ? 'http://127.0.0.1:8000' : 'https://console.chowchak.com';
    }

    const brandDefaults = {
        whatsapp_number: "919257915113",
        phone_number_1: "+91-92579-15113",
        phone_number_2: "+91-86191-90869",
        primary_email: "info@vrsonisoft.com",
        secondary_email: "support@vrsonisoft.com",
        instagram_link: "https://www.instagram.com/vr_soni_soft/",
        facebook_link: "https://www.facebook.com/",
        linkedin_link: "https://linkedin.com/company/vr-soni-soft",
        github_link: "https://github.com/vrsonisoft",
        twitter_link: "https://www.twitter.com/"
    };

    function ensureAbsoluteUrl(url) {
        if (!url) return '';
        url = url.trim();
        if (url === '' || url === '#') return '';
        if (!url.startsWith('http://') && !url.startsWith('https://')) {
            return 'https://' + url;
        }
        return url;
    }

    function cleanWaForUrl(num) {
        if (!num) return '';
        let digits = num.toString().replace(/[^\d]/g, '');
        if (digits.length === 10) digits = '91' + digits;
        return digits;
    }

    function formatWhatsAppDisplay(num) {
        if (!num) return '+91 92579 15113';
        const str = num.toString().trim();
        const digits = str.replace(/[^\d]/g, '');
        if (digits.length === 10) return `+91 ${digits.slice(0, 5)} ${digits.slice(5)}`;
        if (digits.startsWith('91') && digits.length === 12) return `+91 ${digits.slice(2, 7)} ${digits.slice(7)}`;
        if (str.startsWith('+')) return str;
        return `+${str}`;
    }

    function renderPhones(phone1, phone2) {
        const container = document.getElementById('dynamic-phones-list');
        if (!container) return;

        const items = [
            {
                label: "Sales & Demo Inquiries",
                number: phone1 || brandDefaults.phone_number_1,
                raw: (phone1 || brandDefaults.phone_number_1).replace(/[^\d+]/g, '')
            },
            {
                label: "Technical & Hardware Support",
                number: phone2 || brandDefaults.phone_number_2,
                raw: (phone2 || brandDefaults.phone_number_2).replace(/[^\d+]/g, '')
            }
        ];

        container.innerHTML = items.map(item => `
            <div class="cc-inner-row">
                <div>
                    <span class="cc-row-label-green">${item.label}</span>
                    <div class="cc-row-number">${item.number}</div>
                </div>
                <div style="display:flex; align-items:center; gap:6px; flex-shrink:0;">
                    <a href="tel:${item.raw}" style="padding:6px 12px; border-radius:8px; background:#2E6F40; color:#ffffff; font-size:12px; font-weight:700; display:inline-flex; align-items:center; gap:4px; text-decoration:none;">
                        <svg style="width:13px; height:13px;" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"/></svg>
                        <span>Call</span>
                    </a>
                    <button type="button" onclick="copyContactText('${item.number}', '${item.label}')" class="btn-copy" title="Copy Number">
                        <svg style="width:14px; height:14px;" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg>
                    </button>
                </div>
            </div>
        `).join('');

        // Also update top contact bar
        const topBarPhones = document.querySelectorAll('.top-contact-container a[href^="tel:"]');
        if (topBarPhones.length >= 1 && items[0]) {
            topBarPhones[0].href = `tel:${items[0].raw}`;
            topBarPhones[0].textContent = `🇮🇳 ${items[0].number}`;
        }
        if (topBarPhones.length >= 2 && items[1]) {
            topBarPhones[1].href = `tel:${items[1].raw}`;
            topBarPhones[1].textContent = `🇮🇳 ${items[1].number}`;
        }
    }

    function renderEmails(email1, email2) {
        const container = document.getElementById('dynamic-emails-list');
        if (!container) return;

        const items = [
            {
                label: "Customer & POS Support",
                address: email1 || brandDefaults.primary_email
            },
            {
                label: "Sales & Franchising",
                address: email2 || brandDefaults.secondary_email
            }
        ];

        container.innerHTML = items.map(item => `
            <div class="cc-inner-row">
                <div>
                    <span class="cc-row-label-blue">${item.label}</span>
                    <div class="cc-row-number">${item.address}</div>
                </div>
                <div style="display:flex; align-items:center; gap:6px; flex-shrink:0;">
                    <a href="mailto:${item.address}" style="padding:6px 12px; border-radius:8px; background:#2563eb; color:#ffffff; font-size:12px; font-weight:700; display:inline-flex; align-items:center; gap:4px; text-decoration:none;">
                        <svg style="width:13px; height:13px;" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/></svg>
                        <span>Email</span>
                    </a>
                    <button type="button" onclick="copyContactText('${item.address}', '${item.label}')" class="btn-copy" title="Copy Email">
                        <svg style="width:14px; height:14px;" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg>
                    </button>
                </div>
            </div>
        `).join('');
    }

    function renderSocials(data) {
        const container = document.getElementById('dynamic-social-links');
        if (!container) return;

        const socials = [];
        const waRaw = (data.whatsapp_number || brandDefaults.whatsapp_number).replace(/[^\d]/g, '');
        socials.push({
            name: "WhatsApp",
            url: `https://wa.me/${waRaw}`,
            bg: "#25D366",
            svg: '<svg style="width:18px; height:18px;" fill="currentColor" viewBox="0 0 24 24"><path d="M.057 24l1.687-6.163c-1.041-1.804-1.588-3.849-1.587-5.946.003-6.556 5.338-11.891 11.893-11.891 3.181.001 6.167 1.24 8.413 3.488 2.245 2.248 3.481 5.236 3.48 8.414-.003 6.557-5.338 11.892-11.893 11.892-1.99-.001-3.951-.5-5.688-1.448l-6.305 1.654zm6.597-3.807c1.676.995 3.276 1.591 5.392 1.592 5.448 0 9.886-4.434 9.889-9.885.002-5.462-4.415-9.89-9.881-9.892-5.452 0-9.887 4.434-9.889 9.884-.001 2.225.651 3.891 1.746 5.634l-.999 3.648 3.742-.981zm11.387-5.464c-.074-.124-.272-.198-.57-.347-.297-.149-1.758-.868-2.031-.967-.272-.099-.47-.149-.669.149-.198.297-.768.967-.941 1.165-.173.198-.347.223-.644.074-.297-.149-1.255-.462-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.297-.347.446-.521.151-.172.2-.296.3-.495.099-.198.05-.372-.025-.521-.075-.148-.669-1.611-.916-2.206-.242-.579-.487-.501-.669-.51l-.57-.01c-.198 0-.52.074-.792.372s-1.04 1.016-1.04 2.479 1.065 2.876 1.213 3.074c.149.198 2.095 3.2 5.076 4.487.709.306 1.263.489 1.694.626.712.226 1.36.194 1.872.118.571-.085 1.758-.719 2.006-1.413.248-.695.248-1.29.173-1.414z"/></svg>'
        });

        if (data.instagram_link) {
            socials.push({
                name: "Instagram",
                url: data.instagram_link,
                bg: "#E1306C",
                svg: '<svg style="width:18px; height:18px;" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2.163c3.204 0 3.584.012 4.85.07 3.252.148 4.771 1.691 4.919 4.919.058 1.265.069 1.645.069 4.849 0 3.205-.012 3.584-.069 4.849-.149 3.225-1.664 4.771-4.919 4.919-1.266.058-1.644.07-4.85.07-3.204 0-3.584-.012-4.849-.07-3.26-.149-4.771-1.699-4.919-4.92-.058-1.265-.07-1.644-.07-4.849 0-3.204.013-3.583.07-4.849.149-3.227 1.664-4.771 4.919-4.919 1.266-.057 1.645-.069 4.849-.069zm0-2.163c-3.259 0-3.667.014-4.947.072-4.358.2-6.78 2.618-6.98 6.98-.059 1.281-.073 1.689-.073 4.948 0 3.259.014 3.668.072 4.948.2 4.358 2.618 6.78 6.98 6.98 1.281.058 1.689.072 4.948.072 3.259 0 3.668-.014 4.948-.072 4.354-.2 6.782-2.618 6.979-6.98.059-1.28.073-1.689.073-4.948 0-3.259-.014-3.667-.072-4.947-.196-4.354-2.617-6.78-6.979-6.98-1.281-.059-1.69-.073-4.949-.073zm0 5.838c-3.403 0-6.162 2.759-6.162 6.162s2.759 6.163 6.162 6.163 6.162-2.759 6.162-6.163c0-3.403-2.759-6.162-6.162-6.162zm0 10.162c-2.209 0-4-1.79-4-4 0-2.209 1.791-4 4-4s4 1.791 4 4c0 2.21-1.791 4-4 4zm6.406-11.845c-.796 0-1.441.645-1.441 1.44s.645 1.44 1.441 1.44c.795 0 1.439-.645 1.439-1.44s-.644-1.44-1.439-1.44z"/></svg>'
            });
        }

        if (data.facebook_link) {
            socials.push({
                name: "Facebook",
                url: data.facebook_link,
                bg: "#1877F2",
                svg: '<svg style="width:18px; height:18px;" fill="currentColor" viewBox="0 0 24 24"><path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z"/></svg>'
            });
        }

        if (data.linkedin_link) {
            socials.push({
                name: "LinkedIn",
                url: data.linkedin_link,
                bg: "#0A66C2",
                svg: '<svg style="width:18px; height:18px;" fill="currentColor" viewBox="0 0 24 24"><path d="M19 0h-14c-2.761 0-5 2.239-5 5v14c0 2.761 2.239 5 5 5h14c2.762 0 5-2.239 5-5v-14c0-2.761-2.238-5-5-5zm-11 19h-3v-11h3v11zm-1.5-12.268c-.966 0-1.75-.79-1.75-1.764s.784-1.764 1.75-1.764 1.75.79 1.75 1.764-.783 1.764-1.75 1.764zm13.5 12.268h-3v-5.604c0-3.368-4-3.113-4 0v5.604h-3v-11h3v1.765c1.396-2.586 7-2.777 7 2.476v6.759z"/></svg>'
            });
        }

        if (data.twitter_link) {
            socials.push({
                name: "Twitter / X",
                url: data.twitter_link,
                bg: "#000000",
                svg: '<svg style="width:18px; height:18px;" fill="currentColor" viewBox="0 0 24 24"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>'
            });
        }

        if (data.github_link) {
            socials.push({
                name: "GitHub",
                url: data.github_link,
                bg: "#24292e",
                svg: '<svg style="width:18px; height:18px;" fill="currentColor" viewBox="0 0 24 24"><path d="M12 0C5.37 0 0 5.37 0 12c0 5.31 3.435 9.795 8.205 11.385.6.105.825-.255.825-.57 0-.285-.015-1.23-.015-2.235-3.015.555-3.795-.735-4.035-1.41-.135-.345-.72-1.41-1.23-1.695-.42-.225-1.02-.78-.015-.795.945-.015 1.62.87 1.845 1.23 1.08 1.815 2.805 1.305 3.495.99.105-.78.42-1.305.765-1.605-2.67-.3-5.46-1.335-5.46-5.925 0-1.305.465-2.385 1.23-3.225-.12-.3-.54-1.53.12-3.18 0 0 1.005-.315 3.3 1.23.96-.27 1.98-.405 3-.405s2.04.135 3 .405c2.295-1.56 3.3-1.23 3.3-1.23.66 1.65.24 2.88.12 3.18.765.84 1.23 1.905 1.23 3.225 0 4.605-2.805 5.625-5.475 5.925.435.375.81 1.095.81 2.22 0 1.605-.015 2.895-.015 3.3 0 .315.225.69.825.57A12.02 12.02 0 0024 12c0-6.63-5.37-12-12-12z"/></svg>'
            });
        }

        container.innerHTML = socials.map(item => `
            <a href="${item.url}" target="_blank" rel="noopener noreferrer" class="cc-social-badge" title="${item.name}">
                <div style="width:34px; height:34px; border-radius:10px; background:${item.bg}; color:#ffffff; display:flex; align-items:center; justify-content:center; margin-bottom:6px; box-shadow:0 2px 6px rgba(0,0,0,0.15);">
                    ${item.svg}
                </div>
                <span style="font-size:11px; font-weight:700; text-align:center;">
                    ${item.name}
                </span>
            </a>
        `).join('');

        const waBtn = document.getElementById('btn-whatsapp-chat');
        if (waBtn) {
            const defaultMsg = encodeURIComponent("Hi ChowChak Team, I want to learn more about ChowChak POS for my restaurant.");
            waBtn.href = `https://wa.me/${waRaw}?text=${defaultMsg}`;
        }
    }

    async function loadDynamicContactData() {
        const applyData = (d) => {
            const waRaw = (d.whatsapp_number || brandDefaults.whatsapp_number).toString();
            const waDisplay = formatWhatsAppDisplay(waRaw);
            const waClean = cleanWaForUrl(waRaw);

            const displayEl = document.getElementById('dynamic-whatsapp-display');
            if (displayEl) displayEl.textContent = waDisplay;

            const chatBtn = document.getElementById('btn-whatsapp-chat');
            if (chatBtn) {
                const defaultMsg = encodeURIComponent("Hi ChowChak Team, I want to learn more about ChowChak POS for my restaurant.");
                chatBtn.href = `https://wa.me/${waClean}?text=${defaultMsg}`;
            }

            const copyBtn = document.getElementById('btn-whatsapp-copy');
            if (copyBtn) {
                copyBtn.setAttribute('onclick', `copyContactText('${waDisplay}', 'WhatsApp Number')`);
            }

            renderPhones(d.phone_number_1, d.phone_number_2);
            renderEmails(d.primary_email, d.secondary_email);
            renderSocials(d);
            window.CHOWCHAK_LIVE_SETTINGS = d;
        };

        // 1. Instant fallback render with brandDefaults
        applyData(brandDefaults);

        // 2. Fetch live data from backend API
        const apiBase = getApiBaseUrl();
        const endpoint = `${apiBase}/api/v1/public/social-settings`;

        try {
            const response = await fetch(endpoint, {
                method: 'GET',
                headers: { 'Accept': 'application/json' }
            });

            if (response.ok) {
                const json = await response.json();
                if (json && json.success && json.data) {
                    applyData(json.data);
                }
            }
        } catch (err) {
            console.warn('[ChowChak Contact] Using fallback defaults:', err.message);
        }
    }

    let toastTimeout = null;
    window.showToast = function(message) {
        const toast = document.getElementById('toast');
        const toastMsg = document.getElementById('toast-message');
        if (!toast || !toastMsg) return;

        toastMsg.textContent = message;
        toast.classList.add('show');

        if (toastTimeout) clearTimeout(toastTimeout);
        toastTimeout = setTimeout(() => {
            toast.classList.remove('show');
        }, 3000);
    };

    window.copyContactText = function(text, label) {
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(() => {
                window.showToast(`Copied ${text} to clipboard!`);
            }).catch(() => fallbackCopy(text));
        } else {
            fallbackCopy(text);
        }
    };

    function fallbackCopy(text) {
        const input = document.createElement('input');
        input.value = text;
        document.body.appendChild(input);
        input.select();
        document.execCommand('copy');
        document.body.removeChild(input);
        window.showToast(`Copied ${text} to clipboard!`);
    }

    document.addEventListener('DOMContentLoaded', function() {
        loadDynamicContactData();

        const msgTextarea = document.getElementById('contact-message');
        const charCounter = document.getElementById('char-counter');
        if (msgTextarea && charCounter) {
            msgTextarea.addEventListener('input', function() {
                charCounter.textContent = `${this.value.length} / 500`;
            });
        }

        const form = document.getElementById('chowchak-contact-form');
        const successCard = document.getElementById('form-success-card');
        const submitBtn = document.getElementById('btn-submit-form');
        const submitBtnText = document.getElementById('submit-btn-text');
        const submitBtnSpinner = document.getElementById('submit-btn-spinner');
        const submitBtnIcon = document.getElementById('submit-btn-icon');
        const resetBtn = document.getElementById('btn-reset-form');

        if (form) {
            form.addEventListener('submit', async function(e) {
                e.preventDefault();

                let isValid = true;
                const nameInput = document.getElementById('contact-name');
                const emailInput = document.getElementById('contact-email');
                const phoneInput = document.getElementById('contact-phone');
                const restaurantInput = document.getElementById('contact-restaurant');
                const cityInput = document.getElementById('contact-city');
                const topicInput = document.getElementById('contact-topic');
                const msgInput = document.getElementById('contact-message');

                function validateField(input, isFieldValid) {
                    const errEl = input.parentElement.querySelector('.form-error');
                    if (!isFieldValid) {
                        input.classList.add('error');
                        if (errEl) errEl.style.display = 'block';
                        isValid = false;
                    } else {
                        input.classList.remove('error');
                        if (errEl) errEl.style.display = 'none';
                    }
                }

                validateField(nameInput, nameInput.value.trim().length > 0);
                const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                validateField(emailInput, emailRegex.test(emailInput.value.trim()));
                const cleanPhone = phoneInput.value.replace(/\D/g, '');
                validateField(phoneInput, cleanPhone.length === 10);
                validateField(restaurantInput, restaurantInput.value.trim().length > 0);

                if (!isValid) {
                    window.showToast('Please fix highlighted fields.');
                    return;
                }

                submitBtn.disabled = true;
                submitBtnText.textContent = 'Submitting to ChowChak...';
                submitBtnSpinner.style.display = 'inline-block';
                submitBtnIcon.style.display = 'none';

                const rawName = nameInput.value.trim();
                const rawEmail = emailInput.value.trim();
                const rawRestaurant = restaurantInput.value.trim();
                const rawCity = cityInput ? cityInput.value.trim() : '';
                const rawTopic = topicInput.value;
                const userMsg = msgInput.value.trim();

                const fullMessage = `Restaurant/Outlet: ${rawRestaurant}${rawCity ? ' | City: ' + rawCity : ''}\nRequirements: ${userMsg || 'Requested Demo & Pricing.'}`;

                const payload = {
                    name: rawName,
                    email: rawEmail,
                    phone: cleanPhone,
                    category: rawTopic,
                    message: fullMessage
                };

                const apiBase = getApiBaseUrl();
                const postUrl = `${apiBase}/api/v1/public/inquiry`;

                try {
                    const response = await fetch(postUrl, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Accept': 'application/json'
                        },
                        body: JSON.stringify(payload)
                    });

                    const resData = await response.json().catch(() => ({}));

                    if (response.ok && resData.success) {
                        const inquiryId = (resData.data && resData.data.id) ? resData.data.id : Math.floor(1000 + Math.random() * 9000);
                        const ticketDisplay = `Ticket #CC-INQ-${inquiryId}`;

                        form.style.display = 'none';
                        successCard.style.display = 'block';

                        const ticketEl = document.getElementById('success-ticket-id');
                        const summaryEl = document.getElementById('success-summary-text');
                        const waLink = document.getElementById('success-whatsapp-link');

                        if (ticketEl) ticketEl.textContent = ticketDisplay;
                        if (summaryEl) {
                            summaryEl.innerHTML = `Thank you <strong>${rawName}</strong>! Your inquiry for <strong>${rawRestaurant}</strong> regarding <em>"${rawTopic}"</em> has been saved with <strong>${ticketDisplay}</strong>. A ChowChak consultant will call or WhatsApp you at <strong>+91 ${cleanPhone}</strong> within 15 minutes.`;
                        }
                        if (waLink) {
                            const waMsg = encodeURIComponent(`Hi ChowChak! I just submitted ${ticketDisplay} for ${rawRestaurant}. Looking forward to connecting!`);
                            const waNum = (window.CHOWCHAK_LIVE_SETTINGS && window.CHOWCHAK_LIVE_SETTINGS.whatsapp_number) || brandDefaults.whatsapp_number;
                            waLink.href = `https://wa.me/${waNum.replace(/[^\d]/g, '')}?text=${waMsg}`;
                        }

                        window.showToast(`${ticketDisplay} submitted successfully!`);
                    } else {
                        const errMsg = resData.message || 'Submission failed. Please check inputs and try again.';
                        window.showToast(errMsg);
                    }
                } catch (netErr) {
                    console.error('[ChowChak Contact] Network error:', netErr);
                    window.showToast('Network error connecting to server. Please try again or WhatsApp us directly.');
                } finally {
                    submitBtn.disabled = false;
                    submitBtnText.textContent = 'Submit Message & Request Demo';
                    submitBtnSpinner.style.display = 'none';
                    submitBtnIcon.style.display = 'inline-block';
                }
            });
        }

        if (resetBtn && form && successCard) {
            resetBtn.addEventListener('click', function() {
                form.reset();
                if (charCounter) charCounter.textContent = '0 / 500';
                successCard.style.display = 'none';
                form.style.display = 'flex';
            });
        }
    });
})();
</script>
</body>
</html>
